def reverse(self) -> DropColumnOp:
    return DropColumnOp.from_column_and_tablename(
        self.schema, self.table_name, self.column
    )

def from_column_and_tablename(
    cls,
    schema: Optional[str],
    tname: str,
    col: Column[Any],
) -> AddColumnOp:
    return cls(tname, col, schema=schema)
